const state={route:'home',config:{accounts:false,ai:false,products:{}},user:null,entitlements:[],ipip:[],journey:null,answers:[],idx:0,autoAdvanceTimer:null,result:null,reportHistory:[],journal:[],invites:[],shareUrl:'',inviteCode:'',invite:null,story:0,chapter:0,choices:[],mirror:[],busy:false,toastTimer:null,signMode:'register',consent:false,guestCreatorName:'',dailyMood:'',source:'direct',demoMode:false,demoTogetherAnswers:null};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
async function request(url,{method='GET',json}={}){const res=await fetch(url,{method,credentials:'same-origin',headers:json?{'content-type':'application/json'}:{},body:json?JSON.stringify(json):undefined});const d=await res.json().catch(()=>({}));if(!res.ok)throw Error(d.error||'Request failed');return d}
function getLocal(key,fallback){try{return JSON.parse(localStorage.getItem('mirra2:'+key))??fallback}catch{return fallback}}
function putLocal(key,value){try{localStorage.setItem('mirra2:'+key,JSON.stringify(value))}catch{}}
const localDay=(date=new Date())=>[date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');
const insightPrompts=[
 {title:'Where did you feel most like yourself today?',context:'Notice a moment when you were not trying to perform for anyone.',path:'emotions'},
 {title:'What conversation do you want to have, but keep postponing?',context:'It may help to start by naming what matters to you.',path:'relationships'},
 {title:'What is one choice you made that felt true to you?',context:'A small decision can reveal a larger value.',path:'decisions'},
 {title:'What did you need that you did not ask for?',context:'You are allowed to have needs even when they are inconvenient.',path:'boundaries'},
 {title:'Where did you find a little energy today?',context:'Notice what gave something back, even briefly.',path:'habits'},
 {title:'What surprised you about someone else?',context:'Curiosity often changes the story we tell ourselves.',path:'social'},
 {title:'What small thing is worth carrying into tomorrow?',context:'Progress rarely arrives as one enormous realization.',path:'resilience'},
 {title:'What do you want to make more room for?',context:'Let your priorities be visible in the shape of your day.',path:'values'},
 {title:'When did you notice yourself responding differently?',context:'Change can be quiet, and still be meaningful.',path:'emotions'},
 {title:'What made you feel connected this week?',context:'Connection looks different for everyone.',path:'relationships'},
 {title:'What do you wish someone knew about your inner world?',context:'Understanding begins with the courage to be specific.',path:'social'},
 {title:'Where could you offer yourself more patience?',context:'Your pace does not need to match anyone else’s.',path:'resilience'},
 {title:'What would you ask your future self?',context:'You do not have to know the answer to ask a good question.',path:'decisions'},
 {title:'What felt genuinely good, without needing to be productive?',context:'Pleasure and rest are parts of life, too.',path:'habits'}
];
const todayPrompt=()=>insightPrompts[Math.floor(new Date().setHours(12,0,0,0)/86400000)%insightPrompts.length];
function checkins(){return getLocal('checkins',[]).filter(x=>x&&typeof x.date==='string').slice(-120)}
function hasToday(){return checkins().some(x=>x.date===localDay())}
function consecutiveDays(){const set=new Set(checkins().map(x=>x.date));let count=0,d=new Date();if(!set.has(localDay(d)))d.setDate(d.getDate()-1);while(set.has(localDay(d))){count++;d.setDate(d.getDate()-1)}return count}
function savedDraft(){const d=getLocal('draft',null);return d&&['ipip50',...Object.keys(genres),'together'].includes(d.journey)&&Array.isArray(d.answers)&&Number.isInteger(d.idx)&&d.idx>=0?d:null}
function saveDraft(){if(state.route==='quiz'&&state.journey)putLocal('draft',{journey:state.journey,answers:state.answers,idx:state.idx,date:localDay()})}
function clearDraft(){try{localStorage.removeItem('mirra2:draft')}catch{}}
function trackingId(){let id=getLocal('anonymousVisitor',null);if(typeof id!=='string'||!/^[a-f0-9-]{36}$/.test(id)){id=crypto.randomUUID();putLocal('anonymousVisitor',id)}return id}
async function track(kind,journey='general'){
 // Scripted QA is not a person. Exclude it from all product metrics.
 if(navigator.webdriver===true||new URL(location.href).searchParams.has('mirra_qa'))return;
 if(navigator.doNotTrack==='1'||getLocal('analyticsOff',false)===true)return;
 if(!['landing_view','quiz_started','quiz_first_answer','quiz_completed','invite_created','invite_completed','daily_completed','share_clicked','return_visit','story_started','lesson_completed'].includes(kind))return;
 try{await request('/api/funnel',{method:'POST',json:{visitor:trackingId(),kind,journey,source:state.source}})}catch{}
}
function shareExperience(journey='relationships'){
 const path=journey==='ipip50'||Object.hasOwn(genres,journey)?journey:'relationships';
 const url=location.origin+'/q/'+path+'?utm_source=mirra_share';
 track('share_clicked',path);
 if(navigator.share){navigator.share({title:'A question worth asking · MIRRA',text:'I found a thoughtful reflection on MIRRA. Want to try it?',url}).catch(()=>copy(url))}
 else copy(url);
}
function inviteShare(){const link=state.shareUrl;if(!link)return toast('Complete a Together reflection first.');track('share_clicked','together');if(navigator.share){navigator.share({title:'A reflection for two · MIRRA',text:'I’d love to compare our perspectives. Eight questions, no sign-up needed.',url:link}).catch(()=>copy(link))}else copy(link)}

async function boot(){try{const [config,items,me]=await Promise.all([request('/api/config'),request('/ipip-items.json'),request('/api/me')]);state.config=config;state.ipip=items;state.user=me.user;state.entitlements=me.entitlements||[]}catch(e){console.warn('MIRRA initial state',e);state.config={accounts:false,ai:false,products:{}};try{state.ipip=await request('/ipip-items.json')}catch{state.ipip=[]}}
const url=new URL(location.href);const code=url.searchParams.get('invite');const path=url.pathname.match(/^\/q\/([a-z0-9]+)\/?$/);
const chosen=path?.[1]||url.searchParams.get('start');state.source=(url.searchParams.get('utm_source')||'direct').slice(0,40).replace(/[^a-z0-9_-]/gi,'');
const previousVisit=getLocal('lastVisit',null);const today=localDay();if(previousVisit&&previousVisit!==today)track('return_visit');putLocal('lastVisit',today);
if(code){state.inviteCode=code;state.route='invite';await fetchInvite()}
else if(chosen&&(chosen==='ipip50'||Object.hasOwn(genres,chosen))){state.journey=chosen;state.route='quiz';state.answers=[];state.idx=0;track('quiz_started',chosen)}
else if(['daily','community','discover','together','stories','journal','account','science','learn'].includes(location.hash.slice(1))){state.route=location.hash.slice(1)}
render();track('landing_view')}

function route(name){state.route=name;window.scrollTo({top:0,behavior:'instant'});const url=new URL(location.href);url.searchParams.delete('invite');history.replaceState({},'',(url.pathname.startsWith('/q/')?'/':url.pathname)+(name!=='home'?'#'+name:''));render()}
function refreshNav(){document.querySelectorAll('.desktop-nav [data-route],.bottom-nav [data-route]').forEach(n=>{const on=n.dataset.route===state.route||(state.route==='quiz'&&n.dataset.route==='discover')||(state.route==='report'&&n.dataset.route==='discover');n.classList.toggle('active',on);if(n.closest('.bottom-nav')){if(on)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')}});const account=$('#account-action');if(account)account.innerHTML=state.user?escapeText(state.user.name.split(' ')[0])+' <span>↗</span>':'My space <span>↗</span>'}
function render(){refreshNav();const views={home,discover,quiz,report,together,demoTogether,invite,invites,journal,daily,community,guestInvite,guestSpace,account,mirror,stories,membership,science};app.innerHTML=(views[state.route]||home)();document.title=(state.route==='home'?'MIRRA | The psychology of being human':'MIRRA | '+state.route[0].toUpperCase()+state.route.slice(1));$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')}
const heroFaces=`<figure>${image(photos.hero,'Editorial portrait of a reflective adult')}<figcaption>01 / THE INNER SELF</figcaption></figure><figure>${image(photos.man,'Portrait of a smiling young adult')}<figcaption>02 / CONNECTION</figcaption></figure><figure>${image(photos.older,'Portrait of an older adult')}<figcaption>03 / GROWTH</figcaption></figure>`;
function home(){const draft=savedDraft(),check=hasToday();return `<section class="hero container"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">MIRRA / THE PSYCHOLOGY OF BEING HUMAN</span><h1>Get to know yourself.<br><em>Beautifully.</em></h1><p class="lead">A thoughtful way to explore your inner life, your relationships and the choices that shape your days. No labels to live up to. No account needed to begin.</p><div class="group-buttons">${button('Start a free 3-minute reflection','quick-start')}${button('Explore with a friend','together','')}</div><p class="start-assurance">Thoughtful questions. Private answers. Always free to begin.</p>${draft?`<button class="continue-draft" data-action="resume-quiz"><span><b>Your reflection is here.</b><small>Continue ${escapeText(draft.journey==='together'?'MIRRA Together':cardData(draft.journey).title)} where you left off.</small></span><span aria-hidden="true">↗</span></button>`:''}</div><div class="hero-art">${heroFaces}</div></div></section><section class="container experience-pick" id="start"><div class="section-head"><div><span class="eyebrow">YOUR FIRST THREE MINUTES</span><h2 class="section-title">Start with what<br><em>matters to you.</em></h2></div><p>Pick the question that feels most relevant today. Your first reflection begins immediately, with no sign-up screen.</p></div><div class="entry-grid"><button class="entry-card" data-open="emotions"><span class="entry-index">01 / YOUR INNER WORLD</span><h3>Why do I feel<br><em>this way?</em></h3><span class="entry-footer">8 questions · about 3 minutes <b>↗</b></span></button><button class="entry-card" data-open="relationships"><span class="entry-index">02 / OUR CONNECTIONS</span><h3>How do I<br><em>connect?</em></h3><span class="entry-footer">8 questions · about 3 minutes <b>↗</b></span></button><button class="entry-card" data-open="decisions"><span class="entry-index">03 / CHOICES & VALUES</span><h3>What guides<br><em>my choices?</em></h3><span class="entry-footer">8 questions · about 3 minutes <b>↗</b></span></button></div></section><div class="container marquee-strip"><span>HONEST QUESTIONS</span><i>✳</i><span>MEANINGFUL CONVERSATIONS</span><i>✳</i><span>PERSONAL DISCOVERY</span><i>✳</i><span>AT YOUR OWN PACE</span></div><section class="section container"><div class="section-head"><div><span class="eyebrow">MORE TO EXPLORE</span><h2 class="section-title">Every person has<br><em>many chapters.</em></h2></div><p>From grounded personality research to gentle stories about how we relate, MIRRA offers many ways to be curious about yourself.</p></div>${cards(['ipip50','boundaries','values'])}<div class="group-buttons top-space">${button('The full experience library','discover','')}${button('How our questions work','science','')}</div></section><section class="container feature-split"><div class="feature-copy"><span class="eyebrow">THE SCIENCE OF PERSONALITY</span><h2>Real dimensions.<br><em>More human meaning.</em></h2><p>Go beyond a single personality type. The Personality Atlas uses 50 public-domain items from the International Personality Item Pool, with transparent scoring and careful interpretation.</p><div class="proof"><span>IPIP 50-item Big Five</span><span>No diagnoses or fixed labels</span></div>${button('Explore the Personality Atlas','ipip-direct','')}</div><div class="feature-image">${image(photos.woman,'A woman in natural daylight')}</div></section><section class="container feature-split reverse"><div class="feature-image">${image(photos.couple,'A group of friends together in daylight')}</div><div class="feature-copy"><span class="eyebrow">MIRRA TOGETHER</span><h2>The most interesting<br>thing is <em>between us.</em></h2><p>Answer eight gentle questions, invite someone by private link and see where your perspectives meet. Both of you can take part without creating an account.</p>${button('Make a shared reflection','together')}</div></section><section class="daily-teaser"><div class="container daily-teaser-inner"><div><span class="eyebrow">A DAILY MOMENT OF CLARITY</span><h2>One good question<br>can change <em>your day.</em></h2><p>${escapeText(todayPrompt().title)}</p><span class="daily-small">${check?'You have reflected today. Come back tomorrow for a new question.':'Take two minutes. There is nothing to prove.'}</span></div><div>${button(check?'Return to your reflection':'Answer today’s question','daily')}</div></div></section><section class="quote-section"><div class="container"><span class="eyebrow" style="color:#e8c5a7">WHY MIRRA EXISTS</span><blockquote>“People are more interesting than the labels we give them.”</blockquote><small>MIRRA / OUR POINT OF VIEW</small></div></section><section class="section container"><div class="section-head"><div><span class="eyebrow">EVERY PERSPECTIVE IS WELCOME</span><h2 class="section-title">Many lives.<br><em>Many ways of being.</em></h2></div><p>MIRRA is a place for quieter thinkers, curious conversationalists, analytical minds and people who do not fit neatly into any type.</p></div><div class="portrait-wall"><figure>${image(photos.woman2,'Adult woman in natural light')}</figure><figure>${image(photos.man2,'Adult man in natural light')}</figure><figure>${image(photos.older,'Mature woman portrait')}</figure><figure>${image(photos.woman,'Adult woman portrait')}</figure></div><div class="group-buttons top-space">${button('Discover your next chapter','discover')}${button('The community starts with you','community','')}</div></section>`}
function cardData(key){if(key==='ipip50')return {title:'The Personality Atlas',tag:'FOUNDATIONS / IPIP 50',lede:'A 50 item public domain Big Five questionnaire with published item keys.',image:photos.woman};return {...genres[key],tag:genres[key].tag}}
function cards(keys){return `<div class="journey-grid">${keys.map((key,i)=>{const x=cardData(key);return `<article class="journey-card" role="button" tabindex="0" data-open="${key}"><div class="photo">${image(x.image,x.title)}<span>${x.tag}</span></div><div class="journey-body"><h3>${x.title}</h3><p>${x.lede}</p><div class="journey-footer"><span>${key==='ipip50'?50:genres[key].questions.length} QUESTIONS · ${key==='ipip50'?'10':genres[key].questions.length>8?'5':'3'} MIN</span><b>↗</b></div></div></article>`}).join('')}</div>`}
function intro(label,title,description){return `<section class="page-intro"><div class="container"><span class="eyebrow">${label}</span><h1>${title}</h1><p class="lead">${description}</p></div></section>`}
function discover(){return `${intro('THE MIRRA LIBRARY','Every story begins<br>with <em>curiosity.</em>','Choose a considered path into personality, relationships, emotions, habits and more. There is no perfect response. Just your own.') }<section class="page-body container">${cards(['ipip50',...Object.keys(genres)])}<div class="page-card top-space"><span class="eyebrow">THE ORIGINAL COLLECTION</span><h2 style="font:39px var(--display);margin:10px 0">Nine more journeys, still here.</h2><p class="small-text">Visit the original MIRRA assessment library with 134 questions across nine exploratory experiences.</p><a href="/classic" class="btn small">Visit the original library <span>↗</span></a></div></section>`}
function startQuiz(key){clearTimeout(state.autoAdvanceTimer);state.demoMode=false;state.journey=key;state.answers=[];state.idx=0;saveDraft();track('quiz_started',key);route('quiz')}
function quiz(){const together=state.journey==='together';const ipip=state.journey==='ipip50';const desc=together?{title:'MIRRA Together',lede:'Eight questions to discover where your preferences meet.',image:photos.couple}:cardData(state.journey||'ipip50');const items=together?togetherQuestions.map((text,i)=>({text,options:togetherOptions[i]})):ipip?state.ipip:genres[state.journey]?.questions||[];if(!items.length)return `<div class="container page-body">We could not load this experience. ${button('Explore another','discover')}</div>`;const row=items[state.idx],value=state.answers[state.idx];const options=ipip?['Very inaccurate','Moderately inaccurate','Neither accurate nor inaccurate','Moderately accurate','Very accurate']:row.options;return `<div class="assessment-layout"><section class="assessment-core"><div class="quiz-header"><span>${escapeText(desc.title).toUpperCase()}</span><span>${String(state.idx+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}</span></div><div class="progress"><i style="width:${(state.idx+1)/items.length*100}%"></i></div><div class="assessment-question"><div class="qno">Question ${String(state.idx+1).padStart(2,'0')}.</div><h1>${escapeText(row.text)}</h1><p>${ipip?'As you are in everyday life, not as you wish to be.':desc.lede}</p><div class="answers" role="group" aria-label="Choose your response">${options.map((text,i)=>`<button class="answer ${value===i+1?'selected':''}" data-answer="${i+1}" aria-pressed="${value===i+1}"><span>${i+1}</span><span>${escapeText(text)}</span></button>`).join('')}</div></div><div class="quiz-foot"><button class="btn-link" data-action="previous">← Previous</button><button class="btn dark" data-action="next" ${value?'':'disabled'}>${state.idx+1===items.length?'See my reflection':'Continue'} <span>↗</span></button></div><div class="privacy-note">There are no right answers. You can explore without signing up, and your responses stay private.</div></section><aside class="assessment-image">${image(desc.image,desc.title)}<span class="image-note">A closer look at you.</span></aside></div>`}
function scoreClientIPIP(answers){const names={E:'Extraversion',A:'Agreeableness',C:'Conscientiousness',S:'Emotional Stability',I:'Intellect & Imagination'},values=Object.fromEntries(Object.keys(names).map(k=>[k,[]]));state.ipip.forEach((x,i)=>values[x.dimension].push(x.reverse?6-answers[i]:answers[i]));return {instrument:'IPIP Big Five 50-item markers',dimensions:Object.keys(names).map(id=>{const mean=values[id].reduce((a,b)=>a+b,0)/10;return {id,name:names[id],rawMean:Number(mean.toFixed(2)),index:Math.round((mean-1)*25)}}),method:'Scores are transformed within-scale indices, not population percentiles.',clinical:false}}
async function completeQuiz(){const key=state.journey;if(key==='together'&&state.demoMode){state.demoTogetherAnswers=[...state.answers];state.demoMode=false;clearDraft();route('demoTogether');return}if(key==='together'){if(!state.user){clearDraft();state.pendingTogether=[...state.answers];route('guestInvite');return}try{const d=await request('/api/invites',{method:'POST',json:{answers:state.answers}});state.shareUrl=d.url;await loadInvites();route('invites')}catch(e){toast(e.message)}return}
const count=[1,2,3,4].map(v=>state.answers.filter(x=>x===v).length),winner=count.indexOf(Math.max(...count)),outline=MIRRA_CURRICULUM.journeys[key]?.outcomes?.[winner];const score=key==='ipip50'?scoreClientIPIP(state.answers):outline?{name:outline[0],description:outline[1],practice:outline[2],exploratory:true}:{...summaries[winner],exploratory:true};state.result={journey:key,score,answers:[...state.answers],createdAt:new Date().toISOString()};clearDraft();track('quiz_completed',key);putLocal('recentReport',state.result);const saved=getLocal('localReports',[]);saved.unshift(state.result);putLocal('localReports',saved.slice(0,24));if(state.user){try{const d=await request('/api/reports',{method:'POST',json:{journey:key,answers:state.answers,length:state.answers.length,summary:{label:score.name,description:score.description}}});state.result.score=d.score;await loadReports()}catch(e){toast('Saved on this device. Cloud sync was unavailable.')}}route('report')}
function report(){const r=state.result||getLocal('recentReport',null);if(!r)return `${intro('YOUR PORTRAIT','A space for <em>you.</em>','Complete an experience to see your reflections here.')}${button('Begin now','discover')}`;const scientific=r.journey==='ipip50';const score=r.score;const top=scientific?[...score.dimensions].sort((a,b)=>b.index-a.index)[0]:null;return `<section class="container report-hero"><div><span class="eyebrow">YOUR PRIVATE MIRRA PORTRAIT</span><h1>${scientific?'A portrait of <em>you.</em>':'A little more <em>clarity.</em>'}</h1><p>${scientific?'Your answers offer a view across five personality dimensions. These 0 to 100 scores are not population percentiles, clinical diagnoses or permanent labels.':escapeText(score.description)}</p><span class="eyebrow">${new Date(r.createdAt).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span></div><aside class="report-summary"><span class="eyebrow">YOUR REFLECTION</span><b>${scientific?escapeText(top.name):escapeText(score.name||score.label)}</b><p>${scientific?'Your strongest reported dimension in this assessment. Every dimension matters.':'A style you selected most often across these scenarios.'}</p></aside></section><section class="container report-section"><div><span class="eyebrow">THE DETAILS</span><h2 style="font:56px var(--display)">${scientific?'Your five dimensions.':'A moment of perspective.'}</h2>${scientific?score.dimensions.map(x=>`<div class="report-dimension"><span>${escapeText(x.name)}</span><div class="bar"><span style="width:${x.index}%"></span></div><b>${x.index}</b></div>`).join(''):`<div class="page-card"><p>${escapeText(score.description)}</p><p>When does this approach serve you well? When might another approach be useful?</p></div>`}</div><aside class="report-side"><span class="eyebrow">A NOTE ON INTERPRETATION</span><h2>Curiosity is more useful than a label.</h2><p>${scientific?'This report uses the public-domain IPIP 50-item Big Five markers and published scoring keys. The 0 to 100 numbers are transformed scores within the questionnaire, not percentiles or diagnostic cutoffs.':'These original scenario questions are exploratory prompts, not standardized psychological measurements.'}</p><p>Your story is more complex than any single assessment. Return to it with generosity and an open mind.</p></aside></section><section class="container report-actions"><button class="btn dark" data-action="download-card">Save my portrait <span>↓</span></button><button class="btn" data-action="share-experience">Invite someone to try this <span>↗</span></button>${button('Explore more','discover','')}${button('Invite someone','together','')}${button('Join the First Circle','community','')}${button('Reflect again tomorrow','daily','')}</section>`}

function demoTogether(){
 const a=state.demoTogetherAnswers;
 if(!Array.isArray(a)||a.length!==8)return together();
 const simulated=[2,4,1,2,3,4,1,3];
 const n=a.filter((v,i)=>v===simulated[i]).length;
 const dialogue=togetherQuestions.map((q,i)=>({
  question:q,
  you:togetherOptions[i][a[i]-1]||'Your perspective',
  sample:togetherOptions[i][simulated[i]-1]||'Fictional perspective',
  alike:a[i]===simulated[i]
 }));
 return intro('A FICTIONAL PRACTICE EXPERIENCE','Two perspectives.<br><em>One conversation.</em>','Here is how MIRRA Together works. Alex is a fictional example, not a real member or an AI-powered person. Your answers remain private on this device.')+
 '<section class="container page-body demo-pair">'+
 '<div class="comparison-grid demo-compare-grid"><article class="demo-summary"><span class="eyebrow">YOUR PRACTICE RESULT</span><strong>'+n+' / 8</strong><p>Matching selections. This is not a compatibility score.</p></article>'+
 '<article class="demo-summary"><span class="eyebrow">WHO IS ALEX?</span><strong>A fictional example.</strong><p>Prewritten responses show how the experience feels. No user account or artificial social proof.</p></article></div>'+
 '<div class="section-head top-space"><div><span class="eyebrow">THE CONVERSATION</span><h2 class="section-title">Notice what<br><em>opens up.</em></h2></div><p>Different perspectives are invitations to talk, not a verdict about people.</p></div>'+
 '<div class="demo-rows">'+dialogue.map((x,i)=>
 '<article class="demo-row"><div class="demo-question"><small>QUESTION '+String(i+1).padStart(2,'0')+'</small><h3>'+escapeText(x.question)+'</h3></div>'+
 '<div class="demo-answer"><small>YOUR RESPONSE</small><p>'+escapeText(x.you)+'</p></div>'+
 '<div class="demo-answer"><small>ALEX · FICTIONAL EXAMPLE</small><p>'+escapeText(x.sample)+'</p></div>'+
 '<span class="demo-relation">'+(x.alike?'Similar responses':'Different perspectives')+'</span></article>').join('')+'</div>'+
 '<div class="demo-continue"><span class="eyebrow">READY FOR A REAL CONVERSATION?</span><h2>Someone you actually know may surprise you.</h2><p>Invite a friend or partner to answer privately. MIRRA will reveal your shared perspectives only after they respond.</p>'+
 '<div class="group-buttons"><button class="btn dark" data-action="start-together">Invite a real friend <span>↗</span></button>'+button('Explore more','discover','')+'</div>'+
 '<p class="privacy-note">The example above is scripted and fictional. It is never counted as a person, review, match or community activity.</p></div></section>';
}

function together(){return `${intro('MIRRA TOGETHER','The space<br>between <em>us.</em>','The most interesting discovery is sometimes what happens when two perspectives meet. Explore connection without turning people into compatibility scores.')}<section class="page-body container"><div class="together-banner"><div class="copy"><span class="eyebrow">THE SHARED REFLECTION</span><h2>Two people.<br>Two perspectives.<br>One conversation.</h2><p>Answer eight gentle prompts, then invite someone to do the same. Find shared preferences, differences, and questions worth talking about.</p><div class="group-buttons"><button class="btn cream" data-action="start-together">Create an invitation <span>↗</span></button><button class="btn sample-invite" data-action="demo-together">Try an example first <span>↗</span></button></div><p class="demo-label">Example mode uses a fictional person. No account, real participant or public post is created.</p></div>${image(photos.couple,'Friends walking together outdoors')}</div><div class="two-column top-space"><article class="page-card"><span class="eyebrow">WHAT YOU WILL DISCOVER</span><h2 style="font:38px var(--display)">Common ground.</h2><p>See which answers you share and which open a new conversation. You choose who receives the private invitation.</p></article><article class="page-card"><span class="eyebrow">BUILT FOR TRUST</span><h2 style="font:38px var(--display)">No verdicts.</h2><p>MIRRA does not claim to predict relationship success. It creates opportunities to understand each other more thoughtfully.</p></article></div>${state.user?`<div class="top-space">${button('View my invitations','invites','')}</div>`:''}</section>`}

/* Guest-to-guest reflections use transparent, consent-based share links when
   no durable database exists. No simulated users, server persistence or scoring claims. */
function localInviteEncode(payload){
 const raw=new TextEncoder().encode(JSON.stringify(payload));
 let binary='';for(const c of raw)binary+=String.fromCharCode(c);
 return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}
function localInviteRead(code){
 if(!/^local\.[A-Za-z0-9_-]{8,1200}$/.test(code))throw Error('This invitation link is not valid.');
 const raw=code.slice(6).replace(/-/g,'+').replace(/_/g,'/');
 const bytes=Uint8Array.from(atob(raw),c=>c.charCodeAt(0));
 const p=JSON.parse(new TextDecoder().decode(bytes));
 const valid=a=>Array.isArray(a)&&a.length===8&&a.every(x=>Number.isInteger(x)&&x>=1&&x<=4);
 if(p.v!==1||typeof p.n!=='string'||p.n.trim().length<2||p.n.length>50||!valid(p.a)||((p.b||p.g)&&!(typeof p.g==='string'&&p.g.length<=60&&valid(p.b))))throw Error('This invitation is incomplete or invalid.');
 return p;
}
function localInviteLink(p){return location.origin+'/?invite=local.'+localInviteEncode(p)}
const localStyleLabels=['Clear conversation','A little space','Everyday warmth','Shared curiosity'];
function localInviteComparison(a,b){
 const choices=ans=>Array.from({length:4},(_,i)=>ans.filter(x=>x===i+1).length);
 const first=choices(a),second=choices(b);
 return {sharedChoices:a.filter((v,i)=>v===b[i]).length,total:8,first:localStyleLabels[first.indexOf(Math.max(...first))],second:localStyleLabels[second.indexOf(Math.max(...second))],patterns:togetherQuestions.map((question,i)=>({question,similar:a[i]===b[i]})),note:'Matching choices are conversation prompts, never a compatibility or safety score. The people with this link can see the included responses.'};
}
function localGuide(message){
 const m=message.toLowerCase();
 const prompt=/friend|partner|relationship|family|love|dating/.test(m)?'What would you want the other person to understand about this moment?':/work|career|choice|decision|goal/.test(m)?'Which part of this decision connects to what matters most to you?':/stress|anxious|overwhelm|sad|worry/.test(m)?'What is one small, kind thing you could do for yourself right now?':'When did you notice this most clearly, and what might it be telling you about your needs?';
 return 'A guided question, not an AI or clinical assessment: '+prompt;
}

async function fetchInvite(){try{
 if(state.inviteCode.startsWith('local.')){
  const p=localInviteRead(state.inviteCode);
  state.invite={from:p.n,complete:Boolean(p.b),guestName:p.g||null,local:true,comparison:p.b?localInviteComparison(p.a,p.b):null};
  return;
 }
 const d=await request('/api/together/'+encodeURIComponent(state.inviteCode));state.invite=d.invite;
}catch(e){state.invite={error:e.message}}}
function invite(){const inv=state.invite;if(!inv)return `${intro('MIRRA TOGETHER','Opening your <em>invitation.</em>','')}`;if(inv.error)return `${intro('INVITATION','This link is not <em>available.</em>',escapeText(inv.error))}<section class="page-body container">${button('Back to MIRRA','home')}</section>`;if(inv.complete){const c=inv.comparison;return `${intro('TWO PERSPECTIVES','Where your worlds <em>meet.</em>',escapeText(inv.from)+' and '+escapeText(inv.guestName)+', here is a thoughtful starting point for conversation.')}<section class="page-body container"><div class="comparison-grid"><div><span class="eyebrow">SHARED CHOICES</span><strong>${c.sharedChoices} of ${c.total}</strong><p>This is a count of similar selections, not a compatibility rating.</p></div><div><span class="eyebrow">MOST CHOSEN APPROACHES</span><strong>${escapeText(c.first)}</strong><p>${escapeText(inv.from)} / ${escapeText(c.second)} for ${escapeText(inv.guestName)}</p></div></div><div class="top-space"><h2 style="font:45px var(--display)">Eight places to begin talking.</h2><div class="list-rows">${c.patterns.map(x=>`<div class="list-row"><span>${escapeText(x.question)}</span><small>${x.similar?'Similar responses':'Different perspectives'}</small></div>`).join('')}</div></div><p class="privacy-note">${c.note}</p>${inv.local?'<div class="group-buttons top-space"><button class="btn dark" data-action="share-invite">Share completed reflection ↗</button><button class="btn" data-action="copy-invite">Copy comparison link ↗</button></div><p class="privacy-note">This comparison is encoded in the link; MIRRA does not store it on the server. Anyone with the link can read both sets of choices. Share only with the person you choose.</p>':''}${button('Explore MIRRA','discover')}</section>`}
return `${intro('A PRIVATE INVITATION',escapeText(inv.from)+' invited you<br>to <em>reflect together.</em>','Eight small questions. No wrong answers. Your shared response is visible to anyone who has this invitation link.')}<section class="page-body container"><div class="form-card"><h2>Join the conversation.</h2><form id="guest-name-form"><label class="field"><span>YOUR FIRST NAME</span><input name="name" id="guest-name" required minlength="2" maxlength="60" placeholder="How should we call you?"></label><button class="btn dark" type="submit">Begin reflection <span>↗</span></button></form></div></section>`}
function invites(){if(!state.user){const links=getLocal('guestInvites',[]);return `${intro('YOUR CONNECTIONS','Conversations start<br>with <em>curiosity.</em>','Share a private invitation or begin a new reflection. No account is required.')}<section class="page-body container">${state.shareUrl?`<div class="invite-box"><span class="eyebrow">YOUR PRIVATE INVITATION IS READY</span><h2 style="font:44px var(--display)">Send it to someone you care about.</h2><p>They can respond without registering. Anyone with this link can view the finished comparison.</p><div class="invite-code">${escapeText(state.shareUrl)}</div><div class="group-buttons"><button class="btn dark" data-action="share-invite">Share invitation ↗</button><button class="btn" data-action="copy-invite">Copy link ↗</button></div></div>`:''}<h2 style="font:40px var(--display)">Your invitations on this device.</h2><div class="list-rows">${links.length?links.map(l=>`<div class="list-row"><span>Private shared reflection</span><button class="btn small" data-guest-link="${escapeText(l)}">Copy link ↗</button></div>`).join(''):'<p>Invite someone to begin your first conversation.</p>'}</div><div class="top-space">${button('Begin another conversation','together')}</div></section>`} return `${intro('YOUR CONNECTIONS','Invitations &<br><em>shared reflections.</em>','You control who receives a link. A completed invitation can open an honest and useful conversation.')}<section class="page-body container">${state.shareUrl?`<div class="invite-box"><span class="eyebrow">YOUR INVITATION IS READY</span><h2 style="font:42px var(--display)">A conversation worth sharing.</h2><div class="invite-code">${escapeText(state.shareUrl)}</div><button class="btn dark" data-action="copy-invite">Copy invitation link <span>↗</span></button></div>`:''}<div class="dash-heading"><h2>My invitations.</h2><button class="btn small" data-action="start-together">Create another <span>↗</span></button></div><div class="list-rows">${state.invites.length?state.invites.map(v=>`<div class="list-row"><div><b>${v.complete?'Shared reflection complete':'Awaiting a response'}</b><div class="muted">${new Date(v.created_at).toLocaleDateString()} ${v.guest_name?' · '+escapeText(v.guest_name):''}</div></div><button class="btn small" data-invite-open="${escapeText(v.id)}">${v.complete?'View comparison':'Copy link'} ↗</button></div>`).join(''):'<div class="empty">Your shared experiences will appear here.</div>'}</div></section>`}
function journal(){const local=getLocal('journal',[]),entries=state.user?state.journal:local;const now=new Date(),prompt=prompts[Math.floor(now.getTime()/86400000)%prompts.length];const days=new Set(entries.map(x=>new Date(x.created_at||x.date).toDateString())).size;return `${intro('YOUR PRIVATE JOURNAL','Room to <em>reflect.</em>','A little space to find words for what matters. No performance, no perfect answers.')}<section class="page-body container"><div class="journal-layout"><div><div class="daily-card"><span class="eyebrow">TODAY’S QUESTION</span><h2>${prompt}</h2><p>Begin wherever you are. A sentence is enough.</p></div><form id="journal-form"><label class="field"><span>A THOUGHT OF YOUR OWN</span><textarea required minlength="2" maxlength="3000" name="text" placeholder="I noticed something about myself today…"></textarea></label><button class="btn dark" type="submit">Save my reflection <span>↗</span></button><p class="privacy-note">${state.user?'Saved privately to your account.':state.config.accounts?'Saved privately in this browser. Sign in to sync across devices.':'Saved privately in this browser. Cloud sync is not enabled; copy entries before clearing your browser.'}</p></form></div><aside><span class="eyebrow">THE COLLECTION</span><h2 style="font:55px/1 var(--display);margin:15px 0 26px">Your recent thoughts.</h2><p class="small-text">${entries.length} entries across ${days} days.</p><div class="list-rows">${entries.length?entries.map(x=>`<article class="journal-entry"><time>${new Date(x.created_at||x.date).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}</time><p>${escapeText(x.body||x.text)}</p></article>`).join(''):'<div class="empty">It begins with one honest sentence.</div>'}</div></aside></div></section>`}

function guestInvite(){if(!state.pendingTogether)return together();return `${intro('ONE FINAL DETAIL','Whom should we<br><em>say it’s from?</em>','Just your first name is enough to create a private invitation. No account, email address or payment required.')}<section class="page-body container"><div class="form-card"><span class="eyebrow">A REFLECTION FOR TWO</span><h2>Make it personal.</h2><p>When you share your link, the other person will answer the same eight questions. Only people with your link can see the finished comparison.</p><form id="creator-name-form"><label class="field"><span>YOUR FIRST NAME</span><input name="name" autocomplete="given-name" required minlength="2" maxlength="50" placeholder="What should we call you?"></label><button type="submit" class="btn dark">Create my private invitation <span>↗</span></button><p id="guest-error" class="error"></p></form><p class="privacy-note">${state.config.accounts?'Your first name and answers are held for up to 30 days; anyone with the link can view the finished comparison.':'This free version places your first name and eight choices in the invitation link, not a server database. Anyone with the link can read them. Avoid sensitive details; your guest must share the completed comparison link back.'}</p></div></section>`}
function daily(){const entries=checkins(),done=hasToday(),p=todayPrompt(),streak=consecutiveDays(),days=new Set(entries.map(x=>x.date));return `${intro('A MOMENT OF YOUR OWN','A little space<br>to <em>notice.</em>','One question a day. A private record of moments that matter, with no pressure to keep a perfect streak.')}<section class="container daily-layout"><div class="daily-panel"><div class="daily-header"><span class="eyebrow">TODAY’S REFLECTION</span><span class="daily-date">${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</span></div><h2>${escapeText(p.title)}</h2><p>${escapeText(p.context)}</p>${done?`<div class="daily-complete"><b>Your reflection is here.</b><span>Thank you for taking a moment for yourself. A new question appears tomorrow.</span><div class="group-buttons">${button('Explore an experience','discover','')}${button('Try a reflection for two','together','')}</div></div>`:`<form id="daily-form"><fieldset class="mood-field"><legend>How would you describe today?</legend><div class="mood-options">${['Calm','Hopeful','Thoughtful','Overwhelmed'].map((m,i)=>`<label><input name="mood" type="radio" value="${m}" ${i===2?'checked':''}><span>${m}</span></label>`).join('')}</div></fieldset><label class="field"><span>A THOUGHT, IF YOU WOULD LIKE TO SHARE</span><textarea name="reflection" maxlength="1200" placeholder="Today I noticed…" style="min-height:132px"></textarea></label><button type="submit" class="btn dark">Save today’s moment <span>↗</span></button><p class="privacy-note">Just for you. This check-in stays on this device; signed-in users can also save a copy in their private journal.</p></form>`}</div><aside class="daily-aside"><span class="eyebrow">SMALL MOMENTS ADD UP</span><div class="daily-number">${days.size.toString().padStart(2,'0')}</div><h3>Days you’ve shown up.</h3><p>There is no target to hit. The value is in paying attention.</p><div class="mini-calendar">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const k=localDay(d);return `<div class="${days.has(k)?'marked':''}"><small>${d.toLocaleDateString('en-US',{weekday:'short'})}</small><b>${d.getDate()}</b></div>`}).join('')}</div><div class="daily-streak">${streak} ${streak===1?'day':'days'} in your current run</div><div class="daily-photos">${image(photos.journal,'An open personal journal')}</div></aside></section><section class="section container"><div class="section-head"><div><span class="eyebrow">KEEP EXPLORING</span><h2 class="section-title">A question for<br><em>every season.</em></h2></div><p>If today’s reflection raised a new question, there is a short MIRRA experience to follow it.</p></div>${cards([p.path,'relationships','values'].filter((v,i,a)=>a.indexOf(v)===i))}</section>`}
function community(){return `${intro('A COMMUNITY OF CURIOUS PEOPLE','Good conversations<br>begin <em>somewhere.</em>','MIRRA grows through real conversations, not fabricated feeds or popularity contests. A small beginning can still mean something.')}<section class="page-body container"><div class="community-lede"><div><span class="eyebrow">THE FIRST CIRCLE</span><h2>Invite one person<br>you want to <em>understand.</em></h2><p>No public profile, no popularity score. Eight questions create an invitation to get to know someone a little better.</p>${button('Start a shared reflection','together')}</div><div class="community-photo">${image(photos.couple,'Friends together in daylight')}</div></div><div class="section-head top-space"><div><span class="eyebrow">THIS WEEK’S INVITATIONS</span><h2 class="section-title">Three small ways<br>to <em>connect.</em></h2></div><p>Choose your own pace. These are invitations, not achievements you need to unlock.</p></div><div class="community-actions"><article><span>01</span><h3>Go a little deeper.</h3><p>Take one short experience and ask someone what surprised them about their own results.</p><button class="btn-link" data-open="relationships">Try Relationship Lens ↗</button></article><article><span>02</span><h3>Start a conversation.</h3><p>Share the same eight questions with someone. Notice your differences without turning them into a score.</p><button class="btn-link" data-route="together">Create an invitation ↗</button></article><article><span>03</span><h3>Make room for one thought.</h3><p>Spend two minutes reflecting today. It is often easier to connect when you can hear yourself.</p><button class="btn-link" data-route="daily">Answer today’s question ↗</button></article></div><div class="community-letter founding-circle"><span class="eyebrow">THE FIRST CIRCLE</span><h2>Stay close to what we build next.</h2><p>Help shape MIRRA from the beginning. If you'd like occasional updates about new experiences and invitations to give feedback, leave your email. This is optional; every free reflection remains open to everyone.</p><form id="circle-form"><label class="field"><span>YOUR EMAIL</span><input type="email" name="email" autocomplete="email" maxlength="160" required placeholder="you@example.com"></label><label class="field"><span>WHAT DREW YOU HERE?</span><select name="interest"><option value="self">Understanding myself</option><option value="relationships">Relationships and friendships</option><option value="daily">Daily reflection</option><option value="curiosity">Just curious</option></select></label><label class="circle-consent"><input type="checkbox" name="consent" required><span>I would like occasional email updates from MIRRA about new experiences and opportunities to share feedback. I can unsubscribe from any future message.</span></label><button class="btn dark" type="submit">Join the First Circle <span aria-hidden="true">↗</span></button><p class="privacy-note">No account or payment is required. No mailing is being sent today. We store your email only when you choose to opt in.</p></form></div><div class="community-letter"><span class="eyebrow">A NOTE FROM MIRRA</span><h2>We are building this with the first people who use it.</h2><p>Does a question feel meaningful, awkward, too easy or unhelpful? Tell us in the feedback card. Your ideas can shape what we improve next.</p><form id="feedback-form"><label class="field"><span>WHAT SHOULD MIRRA DO BETTER?</span><textarea name="feedback" required minlength="8" maxlength="1000" placeholder="I wish MIRRA would…"></textarea></label><label class="field"><span>WHAT WERE YOU TRYING TO EXPLORE?</span><select name="area"><option value="design">Design and experience</option><option value="questions">Questions and clarity</option><option value="relationships">Relationships and friends</option><option value="daily">Daily reflections</option><option value="other">Something else</option></select></label><button type="submit" class="btn dark">Send feedback <span>↗</span></button><p class="privacy-note">Please avoid sharing medical details or personally identifying information. Anonymous feedback is stored privately for product improvement.</p></form></div></section>`}
function guestSpace(){if(state.user)return account();const reports=getLocal('localReports',[]),draft=savedDraft(),journal=getLocal('journal',[]),days=checkins().length,links=getLocal('guestInvites',[]);return `${intro('YOUR PERSONAL SPACE','A little more<br><em>of you.</em>','Your reflections are yours. Explore on this device without signing in, and create a free account only if you want to sync them across devices.')}<section class="page-body container"><div class="guest-dashboard"><div class="guest-stats"><span class="eyebrow">YOUR STORY SO FAR</span><h2>Every chapter<br>adds a perspective.</h2><div class="guest-stat-row"><div><b>${reports.length}</b><span>Reflections completed</span></div><div><b>${days}</b><span>Daily check-ins</span></div><div><b>${links.length}</b><span>Shared invitations</span></div></div>${draft?`<button class="btn dark" data-action="resume-quiz">Continue a reflection ↗</button>`:button('Begin your next reflection','discover')}</div><div class="guest-save"><span class="eyebrow">SAVE ACROSS DEVICES</span><h3>Your space can travel with you.</h3><p>${state.config.accounts?'Creating a free account is optional. It lets you save future reports, invitations and journal entries across devices. Reflections already on this device stay here.':'Your free reflections and journal live in this browser while cloud accounts are unavailable. You can keep exploring without creating an account.'}</p>${state.config.accounts?button('Create a free account','account',''):button('Explore more experiences','discover','')}<p class="small-text">No checkout, no subscription and no account needed to explore.</p></div></div><div class="section-head top-space"><div><span class="eyebrow">YOUR REFLECTIONS</span><h2 class="section-title">What you’ve <em>noticed.</em></h2></div><p>You can return to the reflections saved in this browser whenever you want.</p></div><div class="list-rows">${reports.length?reports.map((r,i)=>`<button class="guest-report-row" data-local-report="${i}"><span>${escapeText(r.journey==='ipip50'?'The Personality Atlas':genres[r.journey]?.title||'A personal reflection')}</span><small>${new Date(r.createdAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})} ↗</small></button>`).join(''):'<div class="empty">Your first reflection begins with one good question.</div>'}</div><div class="group-buttons top-space">${button('Reflect on today','daily')}${button('Explore with a friend','together','')}</div><p class="privacy-note">This guest space uses local storage on this device. Clearing browser data removes guest entries. Sign-in is optional for cloud storage.</p><div class="privacy-choice"><div><span class="eyebrow">ANONYMOUS PRODUCT SIGNALS</span><h3>You decide what is measured.</h3><p>Optional anonymous signals help us learn which experiences people begin and complete. We never send your answers, journal text, name or email as analytics events. Turning this off stops future events from this browser.</p></div><button class="btn small" data-action="toggle-analytics">${getLocal('analyticsOff',false)?'Allow anonymous analytics':'Stop anonymous analytics'} ↗</button></div></section>`}
function account(){const u=state.user;return `${intro('YOUR SPACE',u?'Welcome back,<br><em>'+escapeText(u.name)+'.</em>':'A personal space<br>that feels <em>your own.</em>',u?'Your reflections, reports and shared experiences in one thoughtful place.':'Create a private account to keep your reports, journal and invitations together across devices.')}<section class="page-body container">${u?`<div class="account-panel"><div class="page-card"><span class="eyebrow">MY MIRRA PROFILE</span><h2 style="font:45px var(--display)">${escapeText(u.name)}</h2><p class="small-text">${escapeText(u.email)}</p><div class="group-buttons">${button('My reports','account','')}${button('My invitations','invites','')}</div><div class="top-space"><button class="btn-link" data-action="export-data">Export my data ↓</button><p><button class="btn-link" data-action="logout">Sign out ↗</button></p><p><button class="btn-link sensitive" data-action="delete-account">Delete account and data</button></p></div></div><div class="page-card"><span class="eyebrow">COLLECTED REFLECTIONS</span><h2 style="font:45px var(--display)">Your journey so far.</h2><div class="list-rows">${state.reportHistory.length?state.reportHistory.map(x=>`<div class="list-row"><div><b>${escapeText(x.journey==='ipip50'?'The Personality Atlas':genres[x.journey]?.title||x.journey)}</b><div class="muted">${new Date(x.created_at).toLocaleDateString()}</div></div><small>Saved</small></div>`).join(''):'<div class="empty">Nothing saved yet. Your next discovery could begin today.</div>'}</div></div></div>${button('Discover an experience','discover')}`:`<div class="form-card"><span class="eyebrow">${state.signMode==='register'?'NEW TO MIRRA':'WELCOME BACK'}</span><h2>${state.signMode==='register'?'A space for you.':'Make yourself at home.'}</h2><p class="small-text">${state.config.accounts?'Private, secure account storage.':'Account registration is currently unavailable; you can explore assessments without signing in.'}</p><form id="auth-form">${state.signMode==='register'?`<label class="field"><span>YOUR NAME</span><input required name="name" autocomplete="name" minlength="2" placeholder="What should we call you?"></label>`:''}<label class="field"><span>EMAIL ADDRESS</span><input required name="email" type="email" autocomplete="email" placeholder="you@example.com"></label><label class="field"><span>PASSWORD</span><input required name="password" type="password" minlength="10" autocomplete="${state.signMode==='register'?'new-password':'current-password'}" placeholder="At least ten characters"></label>${state.signMode==='register'?`<label class="checkline"><input type="checkbox" name="adult" required> I confirm that I am 18 or older.</label>`:''}<button class="btn dark" type="submit" ${state.config.accounts?'':'disabled'}>${state.signMode==='register'?'Create my space':'Sign in'} <span>↗</span></button><p id="auth-error" class="error"></p></form><button class="btn-link" data-action="toggle-auth">${state.signMode==='register'?'Already have an account? Sign in.':'New here? Create an account.'}</button><p class="privacy-note">MIRRA does not sell your journal or assessment answers. You can export or delete account data whenever you choose. This early version uses email and password authentication; email recovery is not configured yet.</p></div>`}</section>`}
function mirror(){return `${intro('THE PERSONAL MIRROR','A conversation<br>with <em>yourself.</em>','Reflect on situations, decisions and relationships with an attentive guide. Your own words remain the starting point.')}<section class="page-body container"><div class="two-column"><div class="page-card"><span class="eyebrow">REFLECTION COMPANION</span><h2 style="font:53px var(--display);margin:15px 0">A question can change the way you see things.</h2><p class="lead">${state.config.ai?'An AI companion can draw on recent reports you have saved, but only after you give permission for this conversation.':'Guided reflection is available. AI-generated replies will become available when a model provider is connected.'}</p><p class="privacy-note">This tool is for personal reflection. It is not therapy, clinical advice or crisis support.</p></div><div><div class="conversation">${state.mirror.length?state.mirror.map(m=>`<div class="bubble ${m.who==='user'?'self':'agent'}">${escapeText(m.text)}</div>`).join(''):'<div class="bubble agent">Hello. What is something you have been noticing about yourself recently?</div>'}</div>${!state.user&&state.config.ai?`<div class="empty">${button('Sign in to use your personal mirror','account')}</div>`:`<form id="mirror-form"><label class="field"><span>WHAT IS ON YOUR MIND?</span><textarea name="message" required minlength="4" maxlength="1000" placeholder="I have been thinking about…" style="min-height:110px"></textarea></label>${state.config.ai?'<label class="checkline"><input type="checkbox" required name="consent"> I consent to my message and up to three recent saved reports being used to generate this reflection.</label>':'<p class="privacy-note">Guided questions run in this browser. No message is sent to an AI model or saved on our server.</p>'}<button class="btn dark" type="submit">Reflect on this <span>↗</span></button></form>`}</div></div></section>`}
function stories(){const story=storyCollection[state.story]||storyCollection[0];const chapter=story.chapters[state.chapter];return `${intro('INTERACTIVE STORIES','Every choice<br>tells a <em>story.</em>','Small fictional moments, inspired by the delicate art of being human. Your choices shape the conversation, not a diagnosis.')}<section class="page-body container"><div class="tab-row">${storyCollection.map((s,i)=>`<button class="${state.story===i?'on':''}" data-story="${i}">${escapeText(s.title)}</button>`).join('')}</div><div class="story-frame"><div class="story-visual">${image(story.image,'Editorial scene for '+story.title)}</div><div class="story-card"><span class="eyebrow">${story.tag} / CHAPTER ${state.chapter+1} OF ${story.chapters.length}</span><h2>${escapeText(story.title)}</h2><p>${escapeText(chapter.text)}</p>${chapter.choices.map((v,i)=>`<button class="story-choice" data-story-answer="${i}">${i+1}. ${escapeText(v)} <span style="float:right">↗</span></button>`).join('')}<p class="privacy-note">These stories are reflective fiction. There is no scientifically scored result.</p></div></div></section>`}
function membership(){const plans=[{id:'deepDive',name:'Deep Dive',price:'$4.99',time:'one time',copy:'A more detailed personal interpretation and printable report.',features:['Extended report','More reflective prompts','Beautiful print layout']},{id:'plus',name:'MIRRA Plus',price:'$7.99',time:'per month',copy:'A growing personal space with premium journeys and deeper reflection.',features:['All premium chapters','Personal Mirror','Saved history']},{id:'together',name:'Together Plus',price:'$12.99',time:'per month',copy:'Make shared exploration part of your relationship rituals.',features:['Shared reflection library','Conversation collections','Two person experiences']}];return `${intro('MIRRA MEMBERSHIP','More room<br>to <em>discover.</em>','Begin with a free experience. Go deeper only when it feels meaningful to you.')}<section class="page-body container"><div class="pricing-grid">${plans.map((p,i)=>`<article class="price-card ${i===1?'featured':''}"><span class="eyebrow">${p.name.toUpperCase()}</span><h3>${p.name}</h3><div class="price">${p.price}<span style="font:12px var(--sans);margin-left:9px">${p.time}</span></div><p>${p.copy}</p><p>${p.features.join(' · ')}</p><button class="btn ${i===1?'cream':''}" data-checkout="${p.id}" ${state.config.products[p.id]?'':'disabled'}>${state.config.products[p.id]?'Choose '+p.name:'Coming soon'} <span>↗</span></button></article>`).join('')}</div><p class="privacy-note">Membership prices are proposed launch prices. Checkout is available only where a verified payment link is configured. Free experiences remain free. Paid access is not yet automatically unlocked without confirmed Stripe webhook integration.</p></section>`}
function science(){return `${intro('THE SCIENCE & THE ART','Measure carefully.<br>Understand <em>generously.</em>','A responsible approach to personality respects evidence, uncertainty and the fact that people can change.')}<section class="page-body container"><div class="two-column"><article class="page-card"><span class="eyebrow">THE FOUNDATION</span><h2 style="font:50px var(--display)">The Big Five.</h2><p>The 50-item assessment uses the public-domain IPIP Big Five markers. Five dimensions are scored using the published reverse-key scheme, with 10 items per dimension. Our transformed 0 to 100 index is not a population percentile.</p><a class="btn" href="https://ipip.ori.org/new_ipip-50-item-scale.htm" target="_blank" rel="noreferrer">Read the original instrument ↗</a></article><article class="page-card"><span class="eyebrow">THE CREATIVE CHAPTERS</span><h2 style="font:50px var(--display)">Questions worth asking.</h2><p>Original relationship, values and lifestyle journeys are for structured self reflection. Their styles are descriptive prompts, not validated psychometric categories, diagnoses or compatibility predictions.</p>${button('Try a reflection','discover')}</article></div><div class="page-card top-space"><span class="eyebrow">YOUR PRIVACY</span><h2 style="font:43px var(--display)">Your words belong to you.</h2><p>Signed-in accounts store reports, invitations and journal entries in MIRRA's application database. Guest reports and journal entries stay in browser storage. Shared links allow anyone with the link to see the resulting comparison after both participants respond. You can export or delete your account data at any time.</p><div class="privacy-choice"><div><span class="eyebrow">YOUR CHOICE</span><h3>Anonymous usage measurement</h3><p>We use a random browser identifier to understand which journeys are started or completed. Answers and journal text are never included in analytics. You can turn future measurement off at any time.</p></div><button class="btn small" data-action="toggle-analytics">${getLocal('analyticsOff',false)?'Allow anonymous analytics':'Stop anonymous analytics'} ↗</button></div></div></section>`}
async function loadReports(){if(!state.user)return;try{state.reportHistory=(await request('/api/reports')).reports||[]}catch(e){console.warn(e)}}
async function loadInvites(){if(!state.user)return;try{state.invites=(await request('/api/invites')).invites||[]}catch(e){console.warn(e)}}
async function loadJournal(){if(!state.user)return;try{state.journal=(await request('/api/journal')).entries||[]}catch(e){console.warn(e)}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{const box=document.createElement('textarea');box.value=text;document.body.append(box);box.select();document.execCommand('copy');box.remove();toast('Copied to clipboard.')}}
function shareCard(){const r=state.result||getLocal('recentReport',null);if(!r)return;const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#f6f3ed';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#243e31';ctx.fillRect(50,50,980,1250);ctx.fillStyle='#e7e3dc';ctx.font='30px Georgia';ctx.fillText('M I R R A',110,155);ctx.fillStyle='#d5a788';ctx.font='18px Arial';ctx.fillText('A PERSONAL REFLECTION',110,240);ctx.fillStyle='#f7f3eb';ctx.font='78px Georgia';ctx.fillText('A portrait of you.',110,340);if(r.journey==='ipip50'){let y=480;for(const item of r.score.dimensions){ctx.font='25px Arial';ctx.fillText(item.name,110,y);ctx.fillStyle='#536e5e';ctx.fillRect(110,y+23,750,12);ctx.fillStyle='#e0c4aa';ctx.fillRect(110,y+23,750*item.index/100,12);ctx.fillStyle='#f7f3eb';ctx.font='32px Georgia';ctx.fillText(String(item.index),880,y+2);y+=132}}else{ctx.font='50px Georgia';ctx.fillText(String(r.score.name||r.score.label).slice(0,30),110,520)}ctx.font='23px Arial';ctx.fillStyle='#b9c6ba';ctx.fillText('Personal reflection, not a diagnosis.',110,1170);ctx.fillText('mirra / the psychology of being human',110,1235);const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='mirra-personality-portrait.png';a.click();toast('Your portrait is ready.')}
function chooseAnswer(value){
 const index=state.idx,journey=state.journey;
 if(index===0&&!state.answers[0])track('quiz_first_answer',journey||'general');
 state.answers[index]=value;
 saveDraft();render();
 // Quick reflections move forward after a clearly selected answer.
 // Big Five retains explicit Continue for deliberate, psychometric answering.
 clearTimeout(state.autoAdvanceTimer);
 if(journey!=='ipip50'){
  const shortMotion=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  state.autoAdvanceTimer=setTimeout(()=>{
   if(state.route==='quiz'&&state.journey===journey&&state.idx===index&&state.answers[index]===value)action('next');
  },shortMotion?300:530);
 }
}
function navigateActions(el){if(el.dataset.route){const r=el.dataset.route;if(r==='quick-start'||r==='ipip-direct'){startQuiz(r==='quick-start'?'emotions':'ipip50');return true}route(r);if(r==='account')loadReports().then(render);if(r==='journal')loadJournal().then(render);if(r==='invites')loadInvites().then(render);return true}if(el.dataset.open){startQuiz(el.dataset.open);return true}if(el.dataset.answer){chooseAnswer(Number(el.dataset.answer));return true}if(el.dataset.story!==undefined){state.story=Number(el.dataset.story);state.chapter=0;state.choices=[];track('story_started','story'+state.story);render();return true}if(el.dataset.storyAnswer!==undefined){state.choices.push(Number(el.dataset.storyAnswer));state.chapter++;if(state.chapter>=storyCollection[state.story].chapters.length){state.chapter=0;toast('A thoughtful ending. Every choice opened a different conversation.')}render();return true}if(el.dataset.localReport!==undefined){const r=getLocal('localReports',[])[Number(el.dataset.localReport)];if(r){state.result=r;route('report')}return true}if(el.dataset.guestLink){copy(el.dataset.guestLink);return true}if(el.dataset.inviteOpen){state.inviteCode=el.dataset.inviteOpen;fetchInvite().then(()=>{if(state.invite?.complete)route('invite');else copy(location.origin+'/?invite='+state.inviteCode)});return true}if(el.dataset.checkout){const link=state.config.products[el.dataset.checkout];if(!link)return toast('Checkout is not configured yet.');if(!state.user){state.signMode='register';route('account');return toast('Create a private account before purchasing.')}const u=new URL(link);u.searchParams.set('client_reference_id',state.user.id);location.href=u.toString();return true}return false}
async function action(name){if(name==='previous'||name==='next')clearTimeout(state.autoAdvanceTimer);if(name==='previous'){if(state.idx>0){state.idx--;saveDraft();render()}else route('discover')}else if(name==='next'){if(!state.answers[state.idx])return;const len=state.journey==='together'?8:state.journey==='ipip50'?state.ipip.length:genres[state.journey].questions.length;if(state.idx+1<len){state.idx++;saveDraft();render()}else await completeQuiz()}else if(name==='resume-quiz'){const d=savedDraft();if(!d)return toast('No reflection in progress.');state.journey=d.journey;state.answers=d.answers;state.idx=d.idx;route('quiz')}else if(name==='share-experience'){shareExperience(state.result?.journey||'relationships')}else if(name==='share-invite'){inviteShare()}else if(name==='toggle-analytics'){const next=!getLocal('analyticsOff',false);putLocal('analyticsOff',next);if(next){try{localStorage.removeItem('mirra2:anonymousVisitor')}catch{}}render();toast(next?'Anonymous product analytics are now off.':'Anonymous product analytics are now on.')}else if(name==='toggle-auth'){state.signMode=state.signMode==='register'?'login':'register';render()}else if(name==='start-together'){startQuiz('together')}else if(name==='demo-together'){startQuiz('together');state.demoMode=true}else if(name==='copy-invite'){copy(state.shareUrl);track('share_clicked','together')}else if(name==='share-result'){const r=state.result;const s=r.journey==='ipip50'?'My MIRRA Big Five reflection: '+r.score.dimensions.map(x=>x.name+' '+x.index+'/100').join(', '):'My MIRRA reflection: '+(r.score.name||r.score.label)+'. '+r.score.description;copy(s+' · Self reflection only, not a diagnosis.')}else if(name==='download-card')shareCard();else if(name==='logout'){await request('/api/logout',{method:'POST',json:{}}).catch(()=>{});state.user=null;state.entitlements=[];state.reportHistory=[];route('home');toast('You have signed out.')}else if(name==='export-data'){try{const data=await request('/api/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='mirra-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Data export downloaded.')}catch(e){toast(e.message)}}else if(name==='delete-account'){if(!confirm('Permanently delete your MIRRA account, reports, journal and invitations? This cannot be undone.'))return;try{await request('/api/account',{method:'DELETE',json:{}});state.user=null;route('home');toast('Your account was deleted.')}catch(e){toast(e.message)}}}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-route],[data-open],[data-answer],[data-action],[data-story],[data-story-answer],[data-invite-open],[data-local-report],[data-guest-link],[data-checkout]');if(!nav)return;e.preventDefault();if(navigateActions(nav))return;try{await action(nav.dataset.action)}catch(e){toast(e.message)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['auth-form','journal-form','guest-name-form','guest-answer-form','mirror-form','creator-name-form','daily-form','feedback-form','circle-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));try{if(form.id==='creator-name-form'){const name=String(data.name||'').trim();if(name.length<2||!state.pendingTogether)throw Error('Please enter your first name.');if(!state.config.accounts){state.shareUrl=localInviteLink({v:1,n:name,a:state.pendingTogether});}else{const d=await request('/api/together-guest',{method:'POST',json:{name,answers:state.pendingTogether}});state.shareUrl=d.url;}state.pendingTogether=null;const links=getLocal('guestInvites',[]);links.unshift(state.shareUrl);putLocal('guestInvites',links.slice(0,20));track('invite_created','together');route('invites');toast('Your invitation is ready to share.')}else if(form.id==='daily-form'){const today=localDay();if(hasToday())return toast('You already reflected today.');const mood=String(data.mood||'Thoughtful');if(!['Calm','Hopeful','Thoughtful','Overwhelmed'].includes(mood))throw Error('Choose a response.');const reflection=String(data.reflection||'').trim().slice(0,1200);const entries=checkins();entries.push({date:today,mood,reflection});putLocal('checkins',entries.slice(-120));if(state.user&&reflection){try{await request('/api/journal',{method:'POST',json:{text:'Today’s reflection: '+reflection}})}catch{}}track('daily_completed','daily');route('daily');toast('Your moment is saved.')}else if(form.id==='circle-form'){if(!form.querySelector('[name=consent]')?.checked)throw Error('Please choose whether to receive updates.');await request('/api/first-circle',{method:'POST',json:{email:String(data.email||'').trim(),interest:String(data.interest||'curiosity'),consent:true,source:state.source}});form.reset();toast('Thank you for joining MIRRA’s First Circle.')}else if(form.id==='feedback-form'){const text=String(data.feedback||'').trim();if(text.length<8)throw Error('Please add a little more detail.');await request('/api/feedback',{method:'POST',json:{text,area:String(data.area||'other')}});form.reset();toast('Thank you. Your feedback was received.')}else if(form.id==='auth-form'){const d=await request(state.signMode==='register'?'/api/register':'/api/login',{method:'POST',json:state.signMode==='register'?{...data,adult:form.querySelector('[name=adult]')?.checked}:data});state.user=d.user;await Promise.all([loadReports(),loadJournal(),loadInvites()]);if(state.pendingTogether){state.journey='together';state.answers=state.pendingTogether;state.idx=7;state.pendingTogether=null;await completeQuiz()}else{route('account');toast('Welcome to your space.')}}else if(form.id==='journal-form'){const text=data.text.trim();if(state.user){await request('/api/journal',{method:'POST',json:{text}});await loadJournal()}else{const local=getLocal('journal',[]);local.unshift({text,date:new Date().toISOString()});putLocal('journal',local)}render();toast('Reflection saved privately.')}else if(form.id==='guest-name-form'){state.guestName=data.name;state.journey='together';state.answers=[];state.idx=0;state.guestMode=true;route('quiz')}else if(form.id==='mirror-form'){state.mirror.push({who:'user',text:data.message});render();if(!state.config.ai){state.mirror.push({who:'agent',text:localGuide(data.message)});render()}else{const d=await request('/api/mirror',{method:'POST',json:{message:data.message}});state.mirror.push({who:'agent',text:d.answer});render()}} }catch(err){const target=$('#auth-error');if(target)target.textContent=err.message;else toast(err.message)}});
// Guest Together submission is intentionally separate from signed-in invitation creation.
const originalComplete=completeQuiz;
completeQuiz=async function(){if(state.guestMode&&state.journey==='together'){try{
 if(state.inviteCode.startsWith('local.')){
  const p=localInviteRead(state.inviteCode);
  const result={v:1,n:p.n,a:p.a,g:String(state.guestName||'Guest').slice(0,60),b:state.answers};
  state.shareUrl=localInviteLink(result);
  state.inviteCode='local.'+localInviteEncode(result);
  state.guestMode=false;
  await fetchInvite();route('invite');
  history.replaceState({},'',state.shareUrl);
  toast('Your shared reflection is ready. Share the completed link back.');
 }else{
  await request('/api/together/'+state.inviteCode+'/answer',{method:'POST',json:{name:state.guestName,answers:state.answers}});
  state.guestMode=false;await fetchInvite();route('invite');
 }
 }catch(e){toast(e.message)}return}return originalComplete()};
$('#menu-toggle').addEventListener('click',()=>{const nav=$('#mobile-nav');nav.hidden=!nav.hidden;$('#menu-toggle').setAttribute('aria-expanded',String(!nav.hidden))});
window.addEventListener('keydown',e=>{if(state.route!=='quiz'||/input|textarea/i.test(document.activeElement?.tagName||''))return;const max=state.journey==='ipip50'?5:4;if(/^[1-5]$/.test(e.key)&&Number(e.key)<=max){chooseAnswer(Number(e.key))}else if(e.key==='Enter'&&state.answers[state.idx])action('next')});
boot();